/**
 * Stackra file contract:
 * Purpose: `codeModule`, the generated `<id>.code.ts` that exports one mobile demo's source text.
 * Boundary: a pure function.
 * Runtime: node
 * Governing contract: showcase redesign spec (2026-10-27) section 7.2.
 */

/** The `.code.ts` content for the demo at `demo` (shown in its header) with source `source`. */
export function codeModule(demo: string, source: string): string {
  return [
    "/**",
    " * Stackra file contract:",
    ` * Purpose: the source text of \`${demo}\`, shown by the mobile Usage tab.`,
    " * Boundary: GENERATED by @stackra/showcase gen (gen-native-sources); do not edit by hand.",
    " * Runtime: react-native",
    " * Governing contract: showcase redesign spec (2026-10-27) section 7.2.",
    " */",
    "",
    `/** The source text of \`${demo}\`, as the Usage tab shows it. */`,
    `export default ${JSON.stringify(source)};`,
    "",
  ].join("\n");
}
